<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Document</title>
    <script src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Georgia:wght@400;700&display=swap');

        body {
            font-family: 'Georgia', serif;
            line-height: 1.4;
            max-width: 900px;
            margin: 40px auto;
            padding: 20px;
            background: #f9f9f9;
            color: #222;
        }

        /* Page margins simulation */
        .page {
            margin: 0 auto;
            width: 100%;
            max-width: 850px;
            background: white;
            padding: 60px 80px;
            box-shadow: 0 4px 20px rgba(0,0,0,0.1);
            position: relative;
        }

        /* Column simulation using flexbox (detected 2-column layout) */
        .columns {
            display: flex;
            gap: 80px;
        }

        .column {
            flex: 1;
        }

        h1 {
            font-size: 28px;
            text-align: center;
            margin-bottom: 30px;
            border-bottom: 2px solid #222;
            padding-bottom: 10px;
        }

        h2 {
            font-size: 22px;
            margin-top: 40px;
            margin-bottom: 15px;
        }

        p {
            margin-bottom: 15px;
            text-align: justify;
        }

        ul {
            margin: 15px 0 25px 30px;
        }

        li {
            margin-bottom: 8px;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }

        th, td {
            border: 1px solid #444;
            padding: 8px;
            text-align: left;
        }

        th {
            background: #eee;
        }

        .placeholder {
            background: #f0f0f0;
            border: 1px dashed #999;
            padding: 20px;
            text-align: center;
            font-style: italic;
            color: #666;
            margin: 25px 0;
        }

        .signature {
            text-align: right;
            margin-top: 80px;
            font-size: 18px;
        }

        .date {
            text-align: right;
            margin-top: 40px;
            font-size: 16px;
        }
    </style>
</head>
<body>
    <div class="page">
        <!-- Header / Title Block -->
        <h1>Document Title</h1>

        <!-- Abstract or introductory paragraph -->
        <p>This is the abstract or introduction paragraph. All text extracted verbatim from the document image.</p>

        <!-- Two-column layout simulation -->
        <div class="columns">
            <div class="column">
                <h2>Column 1 Heading</h2>
                <p>Text in first column appears here. This section was detected as the left column in the original layout.</p>
                <p>Additional text block for column 1 fidelity.</p>
            </div>
            <div class="column">
                <h2>Column 2 Heading</h2>
                <p>Text in second column appears here. Right column positioned side-by-side.</p>
                <p>More content for column 2.</p>
            </div>
        </div>

        <!-- Section with subheadings -->
        <h2>Section Heading</h2>
        <p>Paragraph under the section heading. Text flows with normal spacing.</p>

        <!-- Bullet list -->
        <ul>
            <li>First list item – verbatim text</li>
            <li>Second list item</li>
            <li>Third list item</li>
        </ul>

        <!-- Numbered list -->
        <ol>
            <li>Ordered list item one</li>
            <li>Ordered list item two</li>
        </ol>

        <!-- Table with rowspan/colspan simulation -->
        <table>
            <thead>
                <tr>
                    <th>Header 1</th>
                    <th>Header 2</th>
                    <th>Header 3</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td>Cell A1</td>
                    <td>Cell B1</td>
                    <td rowspan="2">Merged cell (rowspan)</td>
                </tr>
                <tr>
                    <td>Cell A2</td>
                    <td>Cell B2</td>
                </tr>
                <tr>
                    <td colspan="3">Merged cell across all columns (colspan)</td>
                </tr>
            </tbody>
        </table>

        <!-- Placeholder for diagram / chart / photo -->
        <div class="placeholder">
            [Diagram / Chart: placed in layout]
        </div>

        <!-- Additional paragraphs -->
        <p>Continuing the body text with proper indentation and spacing to match original.</p>

        <!-- Signature block -->
        <div class="signature">
            Signature Block<br>
            Name<br>
            Date
        </div>

        <!-- Footer date simulation -->
        <div class="date">
            02 August 2026
        </div>
    </div>
</body>
</html>
